using System;using System.Linq;using System.Globalization;using System.Collections.Generic;using System.Windows;using System.Windows.Media;using System.Windows.Input;
class ArchiveSeries {public string Label,Color;public double?[] Values;}
class ArchivePlot:FrameworkElement {
 public DateTime[] Dates=new DateTime[0];public ArchiveSeries[] Series=new ArchiveSeries[0];public bool Bars=true,Lines=true;public string Unit="";public double? Maximum;
 public ArchivePlot(){Height=300;MinWidth=650;MouseMove+=(s,e)=>{if(Dates.Length==0)return;int i=Math.Max(0,Math.Min(Dates.Length-1,(int)((e.GetPosition(this).X-64)/Math.Max(1,(ActualWidth-84)/Dates.Length))));ToolTip=Dates[i].ToString("yyyy-MM-dd")+String.Join("",Series.Select(a=>"\n"+a.Label+"："+(a.Values[i].HasValue?a.Values[i].Value.ToString("N1")+" "+Unit:"无记录")));};}
 static void Text(DrawingContext dc,string t,double x,double y,Brush brush,double dpi){dc.DrawText(new FormattedText(t,CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface("Microsoft YaHei UI"),11,brush,dpi),new Point(x,y));}
 protected override void OnRender(DrawingContext dc){base.OnRender(dc);if(ActualWidth<100||Dates.Length==0)return;double dpi=VisualTreeHelper.GetDpi(this).PixelsPerDip,slot=(ActualWidth-84)/Dates.Length,top=18,height=200;var muted=TryFindResource("DeskMuted") as Brush??Brushes.SlateGray;var grid=TryFindResource("DeskLine") as Brush??Brushes.Gray;double max=Maximum??Math.Max(1,Series.SelectMany(s=>s.Values).Where(v=>v.HasValue).Select(v=>v.Value).DefaultIfEmpty(1).Max()*1.1);for(int j=0;j<=4;j++){double y=top+height*j/4;dc.DrawLine(new Pen(grid,.6),new Point(62,y),new Point(ActualWidth-15,y));Text(dc,(max*(4-j)/4).ToString(max>10000?"0,,.##M":"0.#"),2,y-7,muted,dpi);}for(int i=0;i<Dates.Length;i++){double center=64+slot*(i+.5);if(i%Math.Max(1,(int)Math.Ceiling(38/slot))==0)Text(dc,Dates[i].ToString("MM/dd"),center-16,228,muted,dpi);if(!Series.Any(s=>s.Values[i].HasValue))Text(dc,"—",center-3,top+height-20,muted,dpi);for(int k=0;k<Series.Length;k++){var series=Series[k];if(!series.Values[i].HasValue)continue;var brush=new SolidColorBrush((Color)ColorConverter.ConvertFromString(series.Color));double y=top+height-Math.Max(0,series.Values[i].Value)/max*height;if(Bars){double bar=Math.Max(1,Math.Min(14,slot*.75/Math.Max(1,Series.Length)));dc.PushOpacity(Lines?.46:.85);dc.DrawRoundedRectangle(brush,null,new Rect(center+(k-Series.Length/2.0)*bar,y,Math.Max(1,bar-1),Math.Max(1,top+height-y)),2,2);dc.Pop();}if(Lines){if(i>0&&series.Values[i-1].HasValue){double before=top+height-Math.Max(0,series.Values[i-1].Value)/max*height;dc.DrawLine(new Pen(brush,2),new Point(center-slot,before),new Point(center,y));}dc.DrawEllipse(brush,null,new Point(center,y),2.5,2.5);}}}for(int k=0;k<Series.Length;k++)Text(dc,Series[k].Label,64+k*145,265,new SolidColorBrush((Color)ColorConverter.ConvertFromString(Series[k].Color)),dpi);if(!Bars&&!Lines)Text(dc,"请打开柱状图或折线图图层",80,100,muted,dpi);}
}
class ArchiveSlice {public string Label,Color;public double Value;}
class ArchiveDonut:FrameworkElement {
 public ArchiveSlice[] Slices=new ArchiveSlice[0];public string Caption="";public ArchiveDonut(){Height=210;MinWidth=280;}
 protected override void OnRender(DrawingContext dc){base.OnRender(dc);double total=Slices.Sum(s=>Math.Max(0,s.Value)),dpi=VisualTreeHelper.GetDpi(this).PixelsPerDip;Brush ink=TryFindResource("DeskMuted") as Brush??Brushes.SlateGray;var center=new Point(88,97);dc.DrawEllipse(null,new Pen(ink,21),center,58,58);double angle=-Math.PI/2;for(int i=0;i<Slices.Length;i++){var slice=Slices[i];double portion=total>0?Math.Max(0,slice.Value)/total:0;var brush=new SolidColorBrush((Color)ColorConverter.ConvertFromString(slice.Color));if(portion>0){var pen=new Pen(brush,22);if(portion>.999999)dc.DrawEllipse(null,pen,center,58,58);else{var arc=new StreamGeometry();using(var context=arc.Open()){context.BeginFigure(new Point(center.X+58*Math.Cos(angle),center.Y+58*Math.Sin(angle)),false,false);double end=angle+portion*Math.PI*2;context.ArcTo(new Point(center.X+58*Math.Cos(end),center.Y+58*Math.Sin(end)),new Size(58,58),0,portion>.5,SweepDirection.Clockwise,true,false);}dc.DrawGeometry(null,pen,arc);}angle+=portion*Math.PI*2;}dc.DrawText(new FormattedText(slice.Label+"  "+(total>0?(portion*100).ToString("F1")+"%":"无记录"),CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface("Microsoft YaHei UI"),12,brush,dpi),new Point(180,40+i*28));}dc.DrawText(new FormattedText(total>0?Caption:"暂无记录",CultureInfo.CurrentCulture,FlowDirection.LeftToRight,new Typeface("Microsoft YaHei UI"),11,ink,dpi),new Point(48,91));}
}
